const report = $json.output ?? $json;

const money = (value) =>
  new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: report.currency || 'TND',
    maximumFractionDigits: 2
  }).format(value);

const escapeHtml = (value) =>
  String(value ?? '').replace(/[&<>"']/g, char => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[char]);

const risks = (report.risks || []).map(risk => `
  <section class="item">
    <h3>${escapeHtml(risk.observation)}</h3>
    <p><strong>Business implication:</strong> ${escapeHtml(risk.business_implication)}</p>
    <p><strong>Limitation:</strong> ${escapeHtml(risk.limitation)}</p>
  </section>
`).join('');

const recommendations = (report.recommendations || [])
  .sort((a, b) => a.priority - b.priority)
  .map(item => `
    <section class="item">
      <h3>Priority ${item.priority}: ${escapeHtml(item.action)}</h3>
      <p><strong>Reason:</strong> ${escapeHtml(item.reason)}</p>
      <p><strong>Expected outcome:</strong> ${escapeHtml(item.expected_outcome)}</p>
    </section>
  `).join('');

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>Monthly Management Report</title>
<style>
  body {
    font-family: Arial, sans-serif;
    color: #243247;
    margin: 40px;
    line-height: 1.6;
  }
  h1 { color: #17365d; }
  h2 {
    color: #17365d;
    border-bottom: 2px solid #dce5ef;
    padding-bottom: 8px;
    margin-top: 30px;
  }
  .meta { color: #667085;
    font-size: 14px;
    margin-bottom: 25px;
  }
  .metrics {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 12px;
  }
  .metric {
    border: 1px solid #dce5ef;
    border-radius: 8px;
    padding: 15px;
  }
  .value { font-size: 20px; font-weight: bold; margin-top: 4px; }
  .item {
    border-left: 3px solid #4676a9;
    padding: 8px 16px;
    margin: 14px 0;
    background: #f7f9fc;
  }
  .footer {
    margin-top: 40px;
    color: #667085;
    font-size: 12px;
    border-top: 1px solid #dce5ef;
    padding-top: 12px;
  }
</style>
</head>
<body>

<h1>Monthly Management Report</h1>
<p class="meta">
  ${escapeHtml(report.company_name)} | Reporting Period: ${escapeHtml(report.reporting_month)}
</p>

<h2>1. Executive Summary</h2>
<p>${escapeHtml(report.executive_summary)}</p>

<h2>2. Financial Performance</h2>
<div class="metrics">
  <div class="metric">
    Revenue<div class="value">${money(report.financial_performance.revenue)}</div>
  </div>
  <div class="metric">
    Expenses<div class="value">${money(report.financial_performance.expenses)}</div>
  </div>
  <div class="metric">
    Gross Profit<div class="value">${money(report.financial_performance.gross_profit)}</div>
  </div>
</div>
<p><strong>Gross Profit Margin:</strong> ${escapeHtml(report.financial_performance.gross_profit_margin)}%</p>
<p>${escapeHtml(report.financial_performance.analysis)}</p>

<h2>3. Operational Performance</h2>
<p>${escapeHtml(report.operational_performance)}</p>

<h2>4. Risks and Concerns</h2>
${risks || '<p>No risks were identified.</p>'}

<h2>5. Recommended Management Actions</h2>
${recommendations}

<h2>Data Limitations</h2>
<ul>
${(report.data_limitations || []).map(item =>
  `<li>${escapeHtml(item)}</li>`
).join('')}
</ul>

<div class="footer">
  Generated by OmniFlow AI | Reporting period: ${escapeHtml(report.reporting_month)}
</div>
</body>
</html>
`;

return {
  json: {
    ...report,
    html_report: html
  }
};

const item = $input.first();

item.binary.pdf.fileName = 'Northstar_Management_Report_2026-10.pdf';
item.binary.pdf.mimeType = 'application/pdf';

return item;
